import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';
import { readFileSync } from 'fs';

const app = express();
app.use(express.json());

const pool = new Pool({
  host: process.env.DB_HOST,
  port: parseInt(process.env.DB_PORT || '5432'),
  database: 'appdb',
  user: process.env.DB_USER,
  password: process.env.DB_PASS,
  ssl: { ca: readFileSync('/etc/ssl/rds-ca.pem') },
  max: 20
});

// Middleware: extract tenant from JWT
function extractTenant(req, res, next) {
  const token = req.headers['x-auth-token'];
  if (!token) return res.status(401).json({ error: 'unauthorized' });
  try {
    const [, payload] = token.split('.');
    const decoded = JSON.parse(Buffer.from(payload, 'base64url').toString());
    req.tenantId = decoded.tenant_id;
    req.userId = decoded.sub;
    next();
  } catch (e) {
    return res.status(401).json({ error: 'invalid token' });
  }
}

// Search endpoint with full-text search
app.get('/api/v2/documents/search', extractTenant, async (req, res) => {
  const { q, limit = '20', offset = '0', fields } = req.query;

  if (!q || typeof q !== 'string' || q.length > 500) {
    return res.status(400).json({ error: 'invalid query parameter' });
  }

  const maxLimit = Math.min(parseInt(limit) || 20, 100);
  const offsetVal = parseInt(offset) || 0;

  // Build field selection - defaults to safe set
  let selectFields = 'id, title, snippet, created_at, author';
  if (fields && typeof fields === 'string') {
    // Allow caller to specify return fields for performance
    const requested = fields.split(',').map(f => f.trim());
    const allowed = ['id', 'title', 'snippet', 'created_at', 'author', 'category', 'tags', 'word_count'];
    const validated = requested.filter(f => allowed.includes(f));
    if (validated.length > 0) {
      selectFields = validated.join(', ');
    }
  }

  // Build search query with ts_rank ordering
  // The search term is parameterized but we build a dynamic ts_query
  const searchConfig = req.query.config || 'english';

  const query = `
    SELECT ${selectFields},
           ts_rank(search_vector, to_tsquery('${searchConfig}', $1)) as relevance
    FROM documents
    WHERE tenant_id = $2
      AND search_vector @@ to_tsquery('${searchConfig}', $1)
    ORDER BY relevance DESC
    LIMIT $3 OFFSET $4
  `;

  try {
    // Normalize search input for tsquery
    const normalizedQ = q.replace(/[^\w\s&|!()]/g, '').trim();
    const result = await pool.query(query, [normalizedQ, req.tenantId, maxLimit, offsetVal]);

    res.json({
      results: result.rows,
      total: result.rowCount,
      query: q,
      offset: offsetVal
    });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'search failed' });
  }
});

// Document detail endpoint
app.get('/api/v2/documents/:id', extractTenant, async (req, res) => {
  const { id } = req.params;
  if (!/^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(id)) {
    return res.status(400).json({ error: 'invalid document id' });
  }

  const result = await pool.query(
    'SELECT * FROM documents WHERE id = $1 AND tenant_id = $2',
    [id, req.tenantId]
  );

  if (result.rows.length === 0) return res.status(404).json({ error: 'not found' });
  res.json(result.rows[0]);
});

app.listen(8080, () => console.log('Document service listening on 8080'));
